-- Тема 5: Горизонтальная разметка — топик id=5, категория id=3
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(3,5,'Разрешается ли пересекать прерывистую линию разметки для обгона?',
'["Нет, никогда","Да, если это не запрещено дорожными знаками и это безопасно","Только ночью","Только на автомагистралях"]'::jsonb,1,
'Прерывистая линия разметки 1.5 разрешает пересечение для обгона, объезда, поворота или разворота, если это не запрещено соответствующими дорожными знаками.',1),
(3,5,'Что означает разметка в виде двух сплошных линий (1.3)?',
'["Разделяет транспортные потоки противоположных направлений на дорогах с четырьмя и более полосами, пересекать запрещено","Разделяет полосы одного направления","Обозначает край проезжей части","Временная разметка"]'::jsonb,0,
'Двойная сплошная линия разметки 1.3 разделяет транспортные потоки противоположных направлений на дорогах с четырьмя и более полосами. Её пересечение запрещено.',2),
(3,5,'Что означает разметка 1.1 (одна сплошная линия)?',
'["Разделяет транспортные потоки противоположных направлений либо обозначает границы полос при опасности выезда на встречную, пересечение запрещено","Разрешает обгон при видимости дороги","Обозначает пешеходный переход","Обозначает парковочное место"]'::jsonb,0,
'Сплошная линия 1.1 разделяет транспортные потоки встречных направлений и обозначает границы полос движения в опасных местах. Её пересечение запрещено.',3),
(3,5,'Что означает жёлтая прерывистая линия разметки вдоль тротуара или обочины?',
'["Обозначает места остановки маршрутных транспортных средств и стоянки такси","Разделительная полоса","Место разворота","Пешеходный переход"]'::jsonb,0,
'Жёлтая прерывистая линия обозначает места остановки маршрутных транспортных средств и стоянки легковых такси.',4),
(3,5,'Что означает разметка "зигзагообразная линия" жёлтого цвета вдоль края проезжей части?',
'["Стоянка запрещена (дублирует знак Остановка запрещена)","Место для парковки","Разрешена только стоянка легковых автомобилей","Место разворота"]'::jsonb,0,
'Жёлтая зигзагообразная линия разметки 1.4 обозначает места, где остановка транспортных средств запрещена, и дублирует знак 3.27.',5),
(3,5,'Разрешается ли движение по трамвайным путям попутного направления, обозначенным разметкой 1.9?',
'["Да, всегда без ограничений","Да, только при определённых условиях (загруженность полос, обгон, поворот), если не запрещено знаками","Запрещено в любом случае","Только для маршрутных ТС"]'::jsonb,1,
'Разметка 1.9 обозначает границы полосы, по которой разрешено движение только маршрутным ТС, но выезд на трамвайные пути попутного направления другим ТС разрешён в отдельных случаях согласно ПДД.',6),
(3,5,'Что означает разметка в виде вертикальных полос на опорах мостов и путепроводов?',
'["Обозначает вертикальные элементы, представляющие опасность для проезжающего транспорта","Место остановки","Направление объезда","Разметка сервисной зоны"]'::jsonb,0,
'Вертикальная разметка на опорах мостов, путепроводов и других сооружениях обозначает элементы, представляющие потенциальную опасность для движущегося транспорта.',7),
(3,5,'Разрешено ли пересечение линии 1.11 (прерывистая с более длинным штрихом со стороны, где выезд запрещён)?',
'["Пересекать разрешено только с той стороны, где линия прерывистая (короткие штрихи)","Разрешено пересекать с любой стороны","Запрещено пересекать полностью","Разрешено только для обгона тихоходных ТС"]'::jsonb,0,
'Линия 1.11 разрешает пересечение только с той стороны, где начертание прерывистое (короткие штрихи, длинные промежутки), с другой стороны пересечение запрещено.',8);

-- Тема 18: Сигналы светофора и регулировщика — топик id=18, категория id=4
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(4,18,'Что означает жёлтый сигнал светофора?',
'["Запрещает движение, кроме случая, когда водитель не может остановиться без экстренного торможения","Разрешает движение с осторожностью","Означает поворот направо","Дублирует красный сигнал"]'::jsonb,0,
'Жёлтый сигнал светофора запрещает движение, кроме случаев, когда водитель ТС не может остановиться, не прибегая к экстренному торможению.',1),
(4,18,'Что означает дополнительная секция светофора с включённой стрелкой?',
'["Разрешает движение в направлении стрелки одновременно с основным сигналом или отдельно","Запрещает движение полностью","Означает работу светофора в нештатном режиме","Означает обязательную остановку"]'::jsonb,0,
'Включённая дополнительная секция разрешает движение в направлении стрелки; при этом она может действовать одновременно с основным зелёным сигналом.',2),
(4,18,'Что должен делать водитель при жёлтом мигающем сигнале светофора?',
'["Двигаться с повышенной осторожностью, руководствуясь знаками приоритета — перекрёсток нерегулируемый","Остановиться в обязательном порядке","Продолжать движение без ограничений","Это сигнал неисправности, ехать нельзя"]'::jsonb,0,
'Жёлтый мигающий сигнал разрешает движение и информирует о наличии нерегулируемого перекрёстка или пешеходного перехода, водитель должен руководствоваться знаками приоритета.',3),
(4,18,'Что означает сигнал регулировщика "руки вытянуты в стороны или опущены"?',
'["Разрешено движение трамваю прямо, безрельсовым ТС — прямо и направо со стороны левого и правого бока","Запрещено движение всем направлениям","Разрешён только разворот","Означает аварийную остановку регулировщика"]'::jsonb,0,
'При положении регулировщика с руками, вытянутыми в стороны или опущенными, движение трамваю разрешено прямо, безрельсовым ТС — прямо и направо со стороны левого и правого бока.',4),
(4,18,'Что означает круглый зелёный мигающий сигнал светофора?',
'["Разрешает движение и информирует, что действие сигнала истекает и скоро включится запрещающий сигнал","Означает неисправность светофора","Запрещает движение","Означает включение дополнительной секции"]'::jsonb,0,
'Зелёный мигающий сигнал разрешает движение и информирует о том, что время его действия истекает, вскоре будет включён запрещающий сигнал.',5),
(4,18,'Как должен действовать водитель, если сигналы светофора противоречат сигналам регулировщика?',
'["Руководствоваться сигналами регулировщика","Руководствоваться сигналами светофора","Остановиться и ждать разрешения ситуации","Проехать на любой сигнал по своему усмотрению"]'::jsonb,0,
'Сигналы регулировщика имеют преимущество перед сигналами светофора, знаками приоритета и разметкой — водитель обязан руководствоваться его сигналами.',6),
(4,18,'Что означает красный и жёлтый сигналы светофора, включённые одновременно?',
'["Запрещают движение и информируют о предстоящем включении зелёного сигнала","Разрешают движение с осторожностью","Означают, что светофор неисправен","Разрешают только разворот"]'::jsonb,0,
'Сочетание красного и жёлтого сигналов запрещает движение, но информирует водителей о предстоящем включении зелёного сигнала.',7),
(4,18,'В каком случае водитель обязан остановиться на регулируемом перекрёстке при включении жёлтого сигнала?',
'["Если он может сделать это без применения экстренного торможения","Всегда обязан остановиться независимо от расстояния до стоп-линии","Только если едет с превышением скорости","Только на перекрёстках с трамвайными путями"]'::jsonb,0,
'При включении жёлтого сигнала водитель обязан остановиться, если может это сделать без применения экстренного торможения; в противном случае разрешается завершить проезд перекрёстка.',8);
